def semver_sort(versions):
    def parse_version(v):
        # Split by + to separate build metadata
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split by - to separate pre-release
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease = parts[1]
        else:
            version_part = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(int(x) for x in version_part.split('.'))

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
            parsed_prerelease = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
            prerelease_tuple = tuple(parsed_prerelease)
        else:
            prerelease_tuple = None

        return (version_nums, prerelease_tuple)

    def sort_key(v):
        major_minor_patch, prerelease_tuple = parse_version(v)

        # Version with prerelease sorts before version without prerelease
        if prerelease_tuple is None:
            # No prerelease: sort after versions with prerelease
            return (major_minor_patch, (1,))
        else:
            # Has prerelease: sort before versions without prerelease
            return (major_minor_patch, (0, prerelease_tuple))

    # Stable sort to maintain input order for equal precedence
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=lambda x: (sort_key(x[0]), x[1]))
    return [v for v, _ in sorted_versions]

